  ('trail-builder', 'trail-builder', 'Trail Builder', 'Design a mountain bike trail for a client, solving a math problem for every segment you build.', 'lab', 'Algebra, Geometry, Trigonometry, Statistics, Calculus', null, 'mtb', array[]::text[], array[]::text[], array['trail-builder']::text[], 'assets/trailbuilder.jpg', 'learning-lab/trail-builder/', 'all', 'available', 201),
